content.text:
[
  {
    "service": "StorefrontOrderService",
    "method": "getOrders",
    "description": "List all orders authored by the given account (typically email).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Author identifier (email/username/customer id).",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of sf_order with each order's items enriched with their fired Tasks.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "getOrder",
    "description": "Look up an order by its public order number. When `author` is \"system\" the lookup is unscoped; otherwise scoped to the calling user.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Caller identity (\"system\" for unscoped lookup, otherwise the user's id/email).",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public 9-char order number.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of sf_order with task-enriched items.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "getOrderById",
    "description": "Get one order by its sk, with its fired workflow Tasks merged onto each productItem. Used by POS / order-detail screens.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderId",
        "type": "String",
        "description": "sk of the sf_order record.",
        "required": true
      }
    ],
    "returns": "sf_order BaseModel (task-enriched) — throws 404 when not found.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "getTransactions",
    "description": "List a customer's payment transactions across all order/invoice/subscription contexts.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "customer",
        "type": "Object",
        "description": "Customer BaseModel — looked up by email/username/phone/sk.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of sf_transaction.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "getOrderPayments",
    "description": "Get ALL sf_transaction records linked to an order plus computed totals — the authoritative single-call payment view for an order detail screen. Matches transactions whose `data.invoiceNumber` equals the order sk OR the order display number OR the order name, case-insensitive. Computes (services/order-payment-summary) totalPaid (gross collected; a till refund row does not lower it), totalRefunded, netRetained, balance (still owed: orderTotal - totalPaid, 0 once cancelled or refunded), canTakePayment, and a payment status (unpaid / paid-partial / paid / overpaid / partially-refunded / refunded / cancelled).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderIdOrNumber",
        "type": "String",
        "description": "sk, display number, or name of the sf_order. Resolved via findOneAnyId.",
        "required": true
      }
    ],
    "returns": "{ orderId, orderNumber, orderTotal, totalPaid, totalRefunded, netRetained, balance, paymentStatus, canTakePayment, payments: BaseModel[], total }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "getWishlist",
    "description": "List the customer's wishlist entries.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "customer",
        "type": "Object",
        "description": "Customer BaseModel — looked up by email/username/phone/sk.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of sf_wishlist.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderByEmail",
    "description": "Look up ONE order by order number AND the exact email on it (matches `author` or `data.email`, case-insensitive). Used by the order-status-by-email page.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "email",
        "type": "String",
        "description": "The exact email on the order (not a pattern).",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      }
    ],
    "returns": "sf_order BaseModel (not task-enriched) or undefined when the number and email do not match.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderRemove",
    "description": "Hard-delete an order belonging to the caller. NOTE: existing implementation does not await `getOrder`; use `orderCancel` for the soft-cancel + refund flow.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Caller identity used as the deletion author.",
        "required": true
      },
      {
        "name": "orderId",
        "type": "String",
        "description": "Order number / id used to look the order up.",
        "required": true
      }
    ],
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderRefund",
    "description": "Refund an order through the gateway by order number, or by payment reference (e.g. pi_…). Tracks each refund in `data.refundHistory`, supports partial refunds, updates the order status to refunded/partially_refunded.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "identifier",
        "type": "String",
        "description": "Order number, OR a payment reference like `pi_xxx`.",
        "required": true
      },
      {
        "name": "refundInfo",
        "type": "Object",
        "description": "{ amount?: number (defaults to full remainder), reason?: string, items?: any[] }",
        "required": true
      }
    ],
    "returns": "{ order, refund, summary: { orderAmount, thisRefund, totalRefunded, remainingRefundable } }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "refundPaymentDirect",
    "description": "Refund a payment directly by payment reference (e.g. Stripe payment intent id). Does NOT require an order — used for standalone invoice payments.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "paymentRef",
        "type": "String",
        "description": "Gateway payment reference (e.g. `pi_xxx`).",
        "required": true
      },
      {
        "name": "info",
        "type": "Object",
        "description": "{ amount: number, reason?: string, invoiceId?: string }",
        "required": true
      }
    ],
    "returns": "Provider refund response.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderCancel",
    "description": "Cancel an order. Cancelling never refunds by itself: pass `refund: true` to also refund a gateway-paid order (manual, till and split payments are refunded with the order refund). Advances the workflow to the Cancelled stage and sends a cancellation email.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "cancelInfo",
        "type": "Object",
        "description": "{ refund?: boolean (default false — only an explicit true refunds), refundAmount?: number (default full), reason?: string }",
        "required": false
      },
      {
        "name": "by",
        "type": "String",
        "required": true
      }
    ],
    "returns": "{ order, refund, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderProcess",
    "description": "Mark order as in fulfillment (\"processing\"). Records status history and advances the workflow stage.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "processInfo",
        "type": "Object",
        "description": "{ note?: string }",
        "required": false
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderShip",
    "description": "Mark order as shipped — appends a shipping entry (carrier, tracking, service, cost), advances workflow, sends a shipping email.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "shipInfo",
        "type": "Object",
        "description": "{ carrier (required), tracking (required), service?, cost?, items?: [{sku, quantity}], note? }",
        "required": true
      }
    ],
    "returns": "{ order, shipping, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderStockRetry",
    "description": "Retry the stock draw-down of an order whose stock needs attention (no unit cost, no single stock location). Takes only what has shipped, never a unit twice, and posts cost of goods.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "author",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "{ order, stock } — stock is data.orderInventory after the retry.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderDeliver",
    "description": "Mark order as delivered — only valid from shipped/in_transit/out_for_delivery. Updates each shipping entry, advances workflow, sends delivery email.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "deliverInfo",
        "type": "Object",
        "description": "{ note?: string }",
        "required": false
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderHold",
    "description": "Put an order on hold (records previousStatus so it can be released back to it). Disallowed from terminal statuses.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "holdInfo",
        "type": "Object",
        "description": "{ reason: string }",
        "required": true
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderRelease",
    "description": "Release an on-hold order back to its previous status (defaults to \"processing\").",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderComplete",
    "description": "Mark a delivered order as completed (terminal state).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderCompleteInPerson",
    "description": "Complete an in-person order (POS tab / counter / pickup) — paid → completed. Records status history, stamps completedAt, advances the order workflow. Refused for unpaid, shipping-path and terminal orders.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "info",
        "type": "Object",
        "description": "{ note?: string }",
        "required": false
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "orderSetStatus",
    "description": "Manually set an order status (operator override). No step preconditions, no automation/events — just sets data.status, stamps the matching timestamp, and records status history. Use the dedicated process/ship/deliver/complete methods when you DO want the events.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "orderNumber",
        "type": "String",
        "description": "The public order number.",
        "required": true
      },
      {
        "name": "statusInfo",
        "type": "Object",
        "description": "{ status: string, note?: string }",
        "required": true
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "findLinkedCustomer",
    "description": "Patch order metadata: shippingInfo, shippingAddress, billingAddress, notes, internalNotes, tags, customFields. Only fields explicitly present in updateData are touched.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "order",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "{ order, message }",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "assertIntentMatchesCart",
    "description": "Create an order from the customer's cart (server cart is the source of truth for items + pricing). Calculates pricing per item, applies cart-level discounts, creates rental records when needed, records the transaction (when gateway info supplied), clears the cart, initializes the workflow, fires affiliate attribution + confirmation email.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "customer",
        "type": "Object",
        "description": "Customer BaseModel (or null for guest checkout).",
        "required": true
      },
      {
        "name": "body",
        "type": "Object",
        "description": "Order payload: { productItems, rentalItems, total, shippingAddress, billingAddress, paymentRef, paymentGateway, currency, email, name, phone, shippingMethod, shippingFee, discounts, cartId, transaction, deposit, depositWaived, freeShipping, affiliateCode }.",
        "required": true
      }
    ],
    "returns": "The persisted sf_order BaseModel (with workflow and rentalIds attached when applicable).",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "joinOrderWorkflow",
    "description": "Resend the order-confirmation/welcome email for an existing order. Used by support flows when the customer reports they didn't receive the original email.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "order",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "The looked-up sf_order BaseModel.",
    "group": "storefront"
  },
  {
    "service": "StorefrontOrderService",
    "method": "createTransaction",
    "description": "Record a payment transaction with gateway-side verification (Stripe/PayPal/GiftCard/AccountBalance) or as a recorded amount (offline/manual/unknown). Returns the persisted sf_transaction.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Caller identity used as the record author.",
        "required": true
      },
      {
        "name": "transactionInfo",
        "type": "Object",
        "description": "{ invoiceNumber, invoiceType, ref, amount, currency, gateway, status, email, remarks, owner, captureInfo, paymentMethod }",
        "required": true
      }
    ],
    "returns": "The persisted sf_transaction BaseModel.",
    "group": "storefront"
  }
]
